  "ai_overview": {
    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "You can apply for a PAN card online through the Protean eGov Technologies Portal, the UTIITSL Portal, or the Income Tax e-Filing Portal for a free instant e-PAN.",
        "snippet_links": [
          {
            "text": "Protean eGov Technologies Portal",
            "link": "https://onlineservices.proteantech.in/paam/endUserRegisterContact.html"
          },
          {
            "text": "UTIITSL Portal",
            "link": "https://www.pan.utiitsl.com/"
          },
          {
            "text": "Income Tax e-Filing Portal",
            "link": "https://www.incometax.gov.in/iec/foportal/help/all-topics/e-filing-services/instant-e-pan"
          }
        ],
        "snippet_highlighted_words": [
          "through the Protean eGov Technologies Portal, the UTIITSL Portal, or the Income Tax e-Filing Portal"
        ],
        "reference_indexes": [
          0,
          1,
          2,
          3
        ]
      },
      {
        "type": "heading",
        "snippet": "Option 1: Apply via Protean (formerly NSDL) or UTIITSL"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Choose the Portal: Visit the Protean PAN Portal or the UTIITSL Portal.",
            "reference_indexes": [
              0,
              2
            ]
          },
          {
            "snippet": "Select Application Type: Choose the new form type (such as Form F093 for Indian citizens or Form F095 for foreign citizens) and select your applicant category (e.g., Individual).",
            "reference_indexes": [
              1
            ]
          },
          {
            "snippet": "Fill Out the Form: Enter your personal information, contact details (mobile number, email), and Aadhaar details.",
            "reference_indexes": [
              0,
              1
            ]
          },
          {
            "snippet": "Submit Documents: Provide a valid proof of identity, address proof, and a separate proof of date of birth (note that Aadhaar alone is no longer accepted as proof of birth for new applications). You can use digital Aadhaar-based e-KYC or e-Sign.",
            "reference_indexes": [
              1,
              4,
              5,
              6
            ]
          },
          {
            "snippet": "Pay the Fee: Pay the processing fee online via net banking, credit card, or debit card.",
            "reference_indexes": [
              4,
              5
            ]
          },
          {
            "snippet": "Save Acknowledgment: Note down the acknowledgment number provided on screen to track your application status.",
            "reference_indexes": [
              7,
              8
            ]
          }
        ]
      },
      {
        "type": "heading",
        "snippet": "Option 2: Free Instant e-PAN (Aadhaar-based)"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Go to the Income Tax e-Filing Portal."
          },
          {
            "snippet": "Click on Instant e-PAN under Quick Links and choose Get New e-PAN."
          },
          {
            "snippet": "Enter your Aadhaar number and complete the OTP verification sent to your linked mobile number."
          },
          {
            "snippet": "Verify your details via DigiLocker to fetch your date of birth proof."
          },
          {
            "snippet": "Download your digitally signed e-PAN instantly at no cost.",
            "reference_indexes": [
              1,
              3
            ]
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "If you'd like, let me know:"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Are you applying as an Indian individual, minor, or foreign citizen?"
          },
          {
            "snippet": "Do you need a physical card or just an instant e-PAN?"
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "I can give you the exact document checklist for your situation."
      }
    ],
